package com.amit.jobagent.application;
import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties("job-agent.content-generation")public record ContentGenerationProperties(boolean enabled,boolean automationEnabled,String model,String reasoningEffort,Duration timeout,int maxRetries,int dailyLimit,long maxInputTokens,long maxOutputTokens,int maxInputCharacters,String promptVersion,String schemaVersion,String templateVersion){public ContentGenerationProperties{if(model==null||model.isBlank())model="gpt-5.6-terra";if(reasoningEffort==null||reasoningEffort.isBlank())reasoningEffort="low";if(timeout==null)timeout=Duration.ofSeconds(30);maxRetries=Math.max(0,maxRetries);if(dailyLimit<=0)dailyLimit=20;if(maxInputTokens<=0)maxInputTokens=24000;if(maxOutputTokens<=0)maxOutputTokens=8000;if(maxInputCharacters<=0)maxInputCharacters=60000;if(promptVersion==null||promptVersion.isBlank())promptVersion="v1";if(schemaVersion==null||schemaVersion.isBlank())schemaVersion="v1";if(templateVersion==null||templateVersion.isBlank())templateVersion="ats-single-column-v1";}}
